    name: { de: "Hafen von Puerto Cabello", hu: "Puerto Cabello kikötője", ro: "Portul Puerto Cabello", en: "Port of Puerto Cabello"},
    description: {
      de: "Der größte und verkehrsreichste Seehafen in Venezuela, der für die nationale Wirtschaft und den internationalen Handel von zentraler Bedeutung ist.",
      hu: "Venezuela legnagyobb és legforgalmasabb tengeri kikötője, amely kiemelt jelentőségű a nemzetközi kereskedelem szempontjából.",
      ro: "Cel mai mare și mai aglomerat port maritim din Venezuela, care este de o importanță centrală pentru comerțul internațional.",
      en: "The largest and busiest seaport in Venezuela, which is of central importance for the national economy and international trade.",
      es: "El puerto marítimo más grande y concurrido de Venezuela, de importancia central para la economía nacional y el comercio internacional.",
      pt: "O maior e mais movimentado porto marítimo da Venezuela, de importância central para a economia nacional e o comércio internacional.",
      fr: "Le plus grand et le plus fréquenté des ports maritimes du Venezuela, d'une importance capitale pour l'économie nationale et le commerce international.",
    },
    descriptionAdvanced: {
      de: "Puerto Cabello ist der wichtigste Handelshafen Venezuelas und liegt an der Karibikküste des Bundesstaates Carabobo. Er schlägt das größte Volumen an Trockenfracht im Land um und ist das logistische Herzstück für die industrielle Zone von Valencia. Die Geschichte des Ortes reicht bis ins 16. Jahrhundert zurück, wobei der Name auf die Legende anspielt, dass das Meer hier so ruhig sei, dass ein Schiff mit einem einzigen Haar ('cabello') am Kai festgemacht werden könne. Während der Kolonialzeit wurde die Stadt durch das Castillo San Felipe, auch bekannt als Fort Libertador, befestigt, um den lukrativen Handel der Guipuzcoana-Kompanie zu schützen. Der Hafen verfügt über spezialisierte Terminals für Getreide, chemische Produkte und Container sowie umfangreiche Werftanlagen der staatlichen Firma DIANCA. Puerto Cabello spielte eine entscheidende Rolle im venezolanischen Unabhängigkeitskrieg, da es 1823 die letzte spanische Festung war, die an die Republikaner fiel. Heute bleibt der Hafen aufgrund seiner Kapazität zur Abfertigung von Massengütern und seiner Anbindung an das nationale Schienennetz von zentraler wirtschaftlicher Bedeutung.",
      hu: "Puerto Cabello Venezuela legforgalmasabb kereskedelmi kikötője, amely Carabobo állam karibi partvidékén található. Ez a létesítmény bonyolítja le az ország legnagyobb szárazáru-forgalmát, és alapvető logisztikai kiszolgálója Valencia ipari övezetének. A kikötő neve egy legendából ered, miszerint a víz itt olyan nyugodt, hogy a hajókat egyetlen hajszállal ('cabello') is ki lehetne kötni. A gyarmati időkben a Guipuzcoana Társaság kereskedelmi monopóliumának védelmére épült fel a Castillo San Felipe erőd, amely ma is meghatározza a város látképét. A kikötő speciális terminálokkal rendelkezik gabona, vegyi anyagok és konténerek fogadására, emellett itt található a DIANCA, az ország legfontosabb hajógyára is. Történelmi szempontból kiemelkedő, hogy 1823-ban ez volt az utolsó spanyol erődítmény, amely megadta magát a függetlenségi harcosoknak. A kikötő modernizált infrastruktúrája és a vasúti hálózathoz való csatlakozása ma is a nemzetgazdaság egyik legfontosabb pillérévé teszi.",
      ro: "Puerto Cabello este cel mai important port comercial din Venezuela, situat pe coasta Mării Caraibilor în statul Carabobo. Acesta gestionează cel mai mare volum de mărfuri uscate din țară și reprezintă centrul logistic principal pentru zona industrială din Valencia. Numele portului provine dintr-o legendă care spune că apele sunt atât de liniștite încât o navă ar putea fi ancorată cu un singur fir de păr ('cabello'). În perioada colonială, a fost protejat de fortul Castillo San Felipe, construit pentru a securiza activitățile comerciale ale Companiei Guipuzcoana. Portul dispune de terminale specializate pentru cereale, produse chimice și containere, precum și de șantierele navale DIANCA, cele mai mari din țară. Din punct de vedere istoric, Puerto Cabello a fost ultima redută spaniolă din Venezuela, capitulând în fața forțelor republicane în anul 1823. În prezent, portul rămâne un punct strategic datorită infrastructurii sale vaste și conexiunii directe cu rețeaua feroviară națională.",
      en: "Puerto Cabello is Venezuela's most active commercial port, located on the Caribbean coast of Carabobo State. It handles the highest volume of dry cargo in the nation and serves as the essential logistical hub for the industrial heartland of Valencia. The port's name is derived from a legend suggesting that the waters are so calm a ship could be moored with a single hair ('cabello'). During the colonial period, it was heavily fortified with the construction of Castillo San Felipe, also known as Fort Libertador, to protect the trade interests of the Guipuzcoana Company. The facility features specialized terminals for grain, chemicals, and containers, alongside the country's primary shipyards, DIANCA. Historically, Puerto Cabello was the site of the final royalist defeat during the Venezuelan War of Independence, falling to republican forces in 1823. Today, its strategic importance is maintained through extensive docking capacity and its role as a terminus for the national railway system.",
      es: "Puerto Cabello es uno de los puertos marítimos más importantes de Venezuela y un centro neurálgico para el comercio nacional e internacional. La ciudad cuenta con una sólida infraestructura logística, esencial para la importación y exportación de bienes industriales y materias primas. Históricamente, la ciudad posee una larga tradición marítima que se remonta a la época colonial. Hoy en día, combina su importancia como centro comercial con un desarrollo urbano activo.",
      pt: "Puerto Cabello é um dos portos marítimos mais importantes da Venezuela e um centro fundamental para o comércio nacional e internacional. A cidade possui uma infraestrutura logística desenvolvida, essencial para a importação e exportação de bens industriais e matérias-primas. Historicamente, a cidade tem uma longa tradição marítima que remonta ao período colonial. Hoje, combina a sua importância como centro comercial com um desenvolvimento urbano ativo.",
      fr: "Puerto Cabello est l'un des ports maritimes les plus importants du Venezuela et une plaque tournante centrale pour le commerce national et international. La ville dispose d'une infrastructure logistique développée, essentielle pour l'importation et l'exportation de produits industriels et de matières premières. Historiquement, la ville possède une longue tradition maritime remontant à l'époque coloniale. Aujourd'hui, elle allie son importance en tant que centre commercial à un développement urbain actif.",
    },
