      hu: ["A kikötőt a 16. században alapították, de igazi fejlődése a 18. században kezdődött.", "A Castillo San Felipe erődöt 1732 és 1741 között építették a spanyolok.", "Venezuela élelmiszer-importjának körülbelül 70%-a ezen a kikötőn keresztül érkezik.", "A DIANCA hajógyárat 1905-ben alapították, és itt található az ország legnagyobb dokkja.", "A kikötő több mint 30 horgonyzóhellyel rendelkezik a különböző árutípusok számára.", "1823 novemberében itt fejeződött be végleg a venezuelai függetlenségi háború."],
      ro: ["Portul a fost înființat în secolul al XVI-lea, devenind un centru major în secolul al XVIII-lea.", "Castillo San Felipe a fost construit între 1732 și 1741 pentru a apăra orașul.", "Aproximativ 70% din importurile alimentare ale Venezuelei trec prin acest port.", "Șantierul naval DIANCA a fost fondat în 1905 și este cel mai important din țară.", "Portul are peste 30 de dane de acostare distribuite în mai multe sectoare.", "În 1823, Puerto Cabello a fost martorul ultimei bătălii pentru independența Venezuelei."],
      en: ["The port was established in the 16th century and expanded by the Guipuzcoana Company.", "Castillo San Felipe was built between 1732 and 1741 to guard the bay.", "Approximately 70% of Venezuela's food imports are processed through Puerto Cabello.", "DIANCA, the national shipyard founded in 1905, is headquartered at the port.", "The facility contains over 30 berths specialized for general cargo and bulk materials.", "The port was the final site of Spanish resistance in Venezuela, ending in 1823."],
      es: ["Puerto Cabello es uno de los puertos con mayor tráfico del país.", "La ciudad sirve como un importante punto de transbordo para bienes industriales.", "La historia marítima se remonta al siglo XVI.", "La instalación es crucial para el suministro de la región central de Venezuela.", "El puerto cuenta con modernas instalaciones de terminales.", "La ciudad está situada estratégicamente a orillas del mar Caribe."],
      pt: ["Puerto Cabello é um dos portos mais movimentados do país.", "A cidade serve como um importante ponto de transbordo para bens industriais.", "A história marítima remonta ao século XVI.", "A instalação é crucial para o abastecimento da região central da Venezuela.", "O porto possui instalações de terminais modernas.", "A cidade está estrategicamente situada no Mar das Caraíbas."],
      fr: ["Puerto Cabello est l'un des ports les plus fréquentés du pays.", "La ville sert de point de transbordement majeur pour les produits industriels.", "L'histoire maritime remonte au XVIe siècle.", "L'installation est cruciale pour l'approvisionnement de la région centrale du Venezuela.", "Le port dispose d'installations de terminaux modernes.", "La ville est stratégiquement située au bord de la mer des Caraïbes."],
