    name: { de: "Hafen von Maracaibo", hu: "Maracaibo kikötője", ro: "Portul Maracaibo", en: "Port of Maracaibo"},
    image: "/poi-images/maracaibo-port-economic-v2.webp",
    description: {
      de: "Ein wichtiger Hafen am Maracaibo-See, der hauptsächlich für den Export von Erdölprodukten und landwirtschaftlichen Gütern genutzt wird.",
      hu: "Egy fontos kikötő a Maracaibo-tavon, amelyet főként kőolajtermékek és mezőgazdasági cikkek exportálására használnak.",
      ro: "Un port important pe lacul Maracaibo, utilizat în principal pentru exportul de produse petroliere și bunuri agricole.",
      en: "An important port on Lake Maracaibo, primarily used for the export of petroleum products and agricultural goods.",
      es: "Un importante puerto en el Lago de Maracaibo, utilizado principalmente para la exportación de productos petrolíferos y productos agrícolas.",
      pt: "Um importante porto no Lago de Maracaibo, utilizado principalmente para a exportação de produtos petrolíferos e bens agrícolas.",
      fr: "Un port important sur le lac Maracaibo, principalement utilisé pour l'exportation de produits pétroliers et de denrées agricoles.",
    },
    descriptionAdvanced: {
      de: "Der Hafen von Maracaibo liegt am westlichen Ufer der Verbindung zwischen dem Maracaibo-See und dem Golf von Venezuela im Bundesstaat Zulia. Er ist von zentraler Bedeutung für den Export von Erdöl und Kohle, zwei der wichtigsten Ressourcen der Region. Die Geschichte des Hafens ist eng mit der Entdeckung des Sees durch Alonso de Ojeda im Jahr 1499 und der offiziellen Stadtgründung 1529 verknüpft. Aufgrund der geringen Wassertiefe des Kanals, der den See mit dem Meer verbindet, sind kontinuierliche Baggerarbeiten notwendig, um den Zugang für große Öltanker zu gewährleisten. Das markanteste Bauwerk in der Nähe ist die Brücke General Rafael Urdaneta, die 1962 eingeweiht wurde und den Hafen logistisch mit dem Rest des Landes verbindet. Neben Rohstoffen werden hier auch landwirtschaftliche Erzeugnisse aus den umliegenden fruchtbaren Regionen sowie Fischereiprodukte umgeschlagen. Der Hafen ist zudem ein kulturelles Symbol für die Region Zulia und spiegelt die industrielle Transformation wider, die durch den Ölboom zu Beginn des 20. Jahrhunderts ausgelöst wurde.",
      hu: "Maracaibo kikötője a Maracaibo-tavat a Venezuelai-öböllel összekötő csatorna nyugati partján fekszik, Zulia államban. Ez a létesítmény kulcsfontosságú az ország kőolaj- és szénexportja szempontjából, amelyek a régió legfőbb erőforrásai. A kikötő története szorosan összefügg a tó 1499-es felfedezésével Alonso de Ojeda által, valamint a város 1529-es megalapításával. Mivel a tavat a tengerrel összekötő csatorna természetes mélysége sekély, folyamatos kotrási munkálatokra van szükség, hogy a hatalmas olajszállító tartályhajók biztonságosan közlekedhessenek. A kikötő közelében található a General Rafael Urdaneta híd, amelyet 1962-ben adtak át, és amely alapvető logisztikai kapcsolatot biztosít az ország többi részével. A nyersanyagokon kívül a kikötő jelentős mennyiségű mezőgazdasági terméket és halászati árut is kezel. Maracaibo kikötője nemcsak gazdasági központ, hanem a 20. század eleji olajrobbanás által kiváltott ipari fejlődés jelképe is.",
      ro: "Portul Maracaibo este situat pe malul vestic al canalului care leagă Lacul Maracaibo de Golful Venezuelei, în statul Zulia. Acesta joacă un rol crucial în exportul de petrol și cărbune, principalele resurse naturale ale acestei regiuni bogate. Istoria portului este strâns legată de descoperirea lacului de către Alonso de Ojeda în 1499 și de fondarea oficială a orașului în 1529. Din cauza adâncimii reduse a canalului natural de navigare, sunt necesare lucrări constante de dragare pentru a permite accesul tancurilor petroliere de mare tonaj. Cea mai cunoscută structură din apropiere este Podul General Rafael Urdaneta, inaugurat în 1962, care asigură conexiunea logistică a portului cu restul țării. Pe lângă materiile prime, portul gestionează și produse agricole din zonele fertile învecinate, precum și produse din industria pescuitului. Portul Maracaibo este un simbol al transformării industriale a Venezuelei, declanșată de boom-ul petrolier de la începutul secolului al XX-lea.",
      en: "The Port of Maracaibo is situated on the western shore of the channel connecting Lake Maracaibo to the Gulf of Venezuela in Zulia State. It serves as a critical terminal for the export of crude oil and coal, the region's most abundant natural resources. The port's history is deeply intertwined with the discovery of the lake by Alonso de Ojeda in 1499 and the formal founding of the city in 1529. Due to the shallow nature of the Tablazo bar, the navigation channel requires continuous dredging to allow the passage of deep-draft oil tankers. A defining feature of the area is the General Rafael Urdaneta Bridge, inaugurated in 1962, which provides a vital logistical link between the port and the rest of the country. Beyond energy exports, the port handles agricultural goods from the surrounding fertile plains and various fishery products. The Port of Maracaibo stands as a symbol of the industrial transformation that reshaped Venezuela following the discovery of massive oil reserves in the early 20th century.",
      es: "El puerto de Maracaibo desempeña un papel fundamental en la conexión económica del Lago de Maracaibo con el comercio mundial. Debido a su proximidad a importantes yacimientos petrolíferos, este puerto es un centro de transbordo clave para productos petroquímicos. La infraestructura marítima apoya significativamente el tráfico de mercancías en la región y constituye un elemento vital para la economía industrial circundante.",
      pt: "O porto de Maracaibo desempenha um papel fundamental na ligação econômica do Lago de Maracaibo ao comércio global. Devido à sua proximidade com importantes campos de petróleo, este porto é um importante centro de transbordo de produtos petroquímicos. A infraestrutura marítima apoia significativamente o fluxo de mercadorias na região e representa uma linha vital para a economia industrial circundante.",
      fr: "Le port de Maracaibo joue un rôle fondamental dans l'intégration économique du lac Maracaibo au commerce mondial. En raison de sa proximité avec d'importants gisements pétroliers, ce port est un centre de transbordement majeur pour les produits pétrochimiques. L'infrastructure maritime soutient largement le trafic de marchandises dans la région et constitue un pilier vital pour l'économie industrielle environnante.",
    },
