    type: "port",
    parent: "VE-O",
    coords: [-64.085, 10.8803],
    name: { de: "Hafen von El Guamache", hu: "El Guamache kikötője", ro: "Portul El Guamache", en: "Port of El Guamache"},
    description: {
      de: "Der wichtigste Fracht- und Kreuzfahrthafen auf der Isla Margarita, der die Insel mit dem Festland und internationalen Zielen verbindet.",
      hu: "A Margarita-sziget legfontosabb teher- és tengerjáró kikötője, amely összeköti a szigetet a szárazfölddel.",
      ro: "Principalul port de marfă și croazieră de pe Insula Margarita, care leagă insula de continent.",
      en: "The main cargo and cruise port on Margarita Island, connecting the island with the mainland and international destinations.",
      es: "El puerto de carga y cruceros más importante de la Isla Margarita, que conecta la isla con tierra firme y destinos internacionales.",
      pt: "O porto de carga e cruzeiros mais importante da Isla Margarita, que conecta a ilha ao continente e a destinos internacionais.",
      fr: "Le port de fret et de croisière le plus important de l'Isla Margarita, reliant l'île au continent et aux destinations internationales.",
    },
    descriptionAdvanced: {
      de: "Der Hafen von El Guamache befindet sich an der Südwestküste der Insel Margarita im Bundesstaat Nueva Esparta. Er ist der wichtigste Anlaufpunkt für Kreuzfahrtschiffe und internationale Fracht auf der Insel und spielt eine zentrale Rolle für den Tourismussektor und die Versorgung der lokalen Bevölkerung. Der Hafen wurde in den 1970er Jahren modernisiert, um den Status Margaritas als zollfreie Zone (Puerto Libre) zu unterstützen. Geografisch liegt El Guamache in einer geschützten Bucht, die ruhiges Wasser und sichere Anlegemanöver garantiert. Neben dem Tourismus dient der Hafen dem Umschlag von Lebensmitteln, Elektronik und Fahrzeugen, die vom Festland oder aus dem Ausland kommen. Die Infrastruktur umfasst spezialisierte Terminals für Passagiere und Container sowie Lagereinrichtungen für verschiedene Güter. El Guamache ist zudem ein wichtiger Knotenpunkt für Fährverbindungen, die die Insel mit den Häfen Puerto La Cruz, Guanta und Cumaná verbinden und somit die logistische Lebensader der Region Nueva Esparta bilden.",
      hu: "El Guamache kikötője Margarita szigetének délnyugati partján fekszik, Nueva Esparta államban. Ez a sziget legfontosabb tengeri csomópontja a nemzetközi tengerjáró hajók és a teherszállítók számára, meghatározó szerepet játszva az idegenforgalomban és a helyi lakosság ellátásában. A kikötőt az 1970-es években modernizálták, hogy támogassa Margarita szabadkikötői (Puerto Libre) státuszát. Földrajzilag El Guamache egy védett öbölben található, amely nyugodt vizet és biztonságos kikötést garantál a hatalmas óceánjárók számára is. A turizmus mellett a kikötő felelős az élelmiszerek, elektronikai cikkek és gépjárművek behozataláért a szárazföldről vagy külföldről. Az infrastruktúra részét képezik a speciális utasterminálok, konténerraktárak és az áruk tárolására szolgáló létesítmények. El Guamache kulcsfontosságú kompösszeköttetést biztosít Puerto La Cruz, Guanta és Cumaná városaival, ezáltal Nueva Esparta régió logisztikai ütőerének számít.",
      ro: "Portul El Guamache este situat pe coasta de sud-vest a Insulei Margarita în statul Nueva Esparta. Reprezintă principalul punct de sosire pentru navele de croazieră și transportul maritim internațional pe insulă, având un rol crucial în sectorul turismului și în aprovizionarea populației locale. Portul a fost modernizat în anii 1970 pentru a sprijini statutul de zonă liberă (Puerto Libre) al insulei Margarita. Din punct de vedere geografic, El Guamache se află într-un golf protejat care garantează ape liniștite și manevre de ancorare sigure. Pe lângă turism, portul gestionează importurile de alimente, electronice și vehicule provenite de pe continent sau din străinătate. Infrastructura sa include terminale specializate pentru pasageri, dane pentru containere și facilități de depozitare. El Guamache este, de asemenea, un nod vital pentru feriboturile care leagă insula de porturile Puerto La Cruz, Guanta și Cumaná, constituind artera logistică principală a regiunii Nueva Esparta.",
      en: "The Port of El Guamache is situated on the southwestern coast of Margarita Island in Nueva Esparta State. It serves as the island's premier gateway for international cruise ships and commercial maritime traffic, playing a central role in both the tourism industry and the logistical supply of the local population. The port underwent significant modernization in the 1970s to bolster Margarita's status as a Free Port (Puerto Libre). Geographically, El Guamache is nestled in a sheltered bay that ensures calm waters and safe docking maneuvers for large ocean liners. Beyond its touristic function, the port facilitates the import of essential food supplies, electronics, and vehicles from the mainland and abroad. The infrastructure includes specialized passenger terminals, container berths, and extensive storage facilities. El Guamache also functions as a critical ferry hub connecting the island with the ports of Puerto La Cruz, Guanta, and Cumaná, forming the essential lifeline for the Nueva Esparta region.",
      es: "El Guamache es la puerta marítima a la turística Isla Margarita. Mientras que el puerto es esencial para el transporte de mercancías y el abastecimiento de la isla con productos del continente, también es una terminal de cruceros significativa. Cruceros de todo el mundo atracan aquí, trayendo turistas que desean explorar el patrimonio cultural y natural de la Isla Margarita. Por lo tanto, El Guamache combina la logística necesaria para el suministro de la isla con el atractivo turístico regional.",
      pt: "El Guamache é a porta marítima para a turística Isla Margarita. Enquanto o porto é essencial para o transporte de mercadorias e o abastecimento da ilha com produtos do continente, é também um terminal de cruzeiros significativo. Cruzeiros de todo o mundo atracam aqui, trazendo turistas que desejam explorar o patrimônio cultural e natural da Isla Margarita. Portanto, El Guamache combina a logística necessária para o abastecimento da ilha com o apelo turístico regional.",
      fr: "El Guamache est la porte maritime de l'île touristique de Margarita. Si le port est essentiel pour le transport de marchandises et l'approvisionnement de l'île depuis le continent, il est également un terminal de croisière important. Des navires du monde entier y font escale, amenant des touristes venus découvrir le patrimoine culturel et naturel de l'Isla Margarita. El Guamache allie ainsi la logistique nécessaire à l'approvisionnement de l'île au rayonnement touristique régional.",
    },
