      en: ["Cruise terminal", "Important for island supply", "Located in the south of Margarita", "Center for tourism"],
      es: ["Terminal de cruceros", "Importante para el suministro de la isla", "Situado en el sur de Margarita", "Centro para el turismo"],
      pt: ["Terminal de cruzeiros", "Importante para o abastecimento da ilha", "Localizado no sul de Margarita", "Centro para o turismo"],
      fr: ["Terminal de croisière", "Important pour l'approvisionnement de l'île", "Situé au sud de Margarita", "Centre pour le tourisme"],
