    name: { de: "Industriehafen Matanzas", hu: "Matanzas ipari kikötő", ro: "Portul Industrial Matanzas", en: "Matanzas Industrial Port"},
    image: "/poi-images/matanzas-industrial-port-economic-v2.webp",
    description: {
      de: "Ein industrieller Schwerlasthafen, der die massiven Stahl- und Aluminiumwerke in Ciudad Guayana direkt bedient.",
      hu: "Ipari nehézrakodó kikötő, amely közvetlenül szolgálja ki Ciudad Guayana hatalmas acél- és alumíniumüzemeit.",
      ro: "Un port industrial de mare tonaj care deservește direct uzinele masive de oțel și aluminiu din Ciudad Guayana.",
      en: "A heavy-duty industrial port that directly serves the massive steel and aluminum plants in Ciudad Guayana.",
      es: "Un puerto industrial de carga pesada que sirve directamente a las enormes plantas de acero y aluminio de Ciudad Guayana.",
      pt: "Um porto industrial de carga pesada que atende diretamente as massivas usinas de aço e alumínio em Ciudad Guayana.",
      fr: "Un port industriel pour charges lourdes qui dessert directement les immenses usines d'acier et d'aluminium de Ciudad Guayana.",
    },
    descriptionAdvanced: {
      de: "Der Industriehafen von Matanzas liegt im Herzen der Industriezone von Puerto Ordaz, Ciudad Guayana, am Ufer des Orinoco-Flusses. Er ist das logistische Zentrum für die massiven staatlichen Betriebe der Corporación Venezolana de Guayana (CVG), darunter das Stahlwerk SIDOR sowie die Aluminiumproduzenten VENALUM und ALCASA. Der Hafen wurde in den 1960er Jahren als integraler Bestandteil des Guayana-Entwicklungsplans konzipiert, um Venezuela als bedeutenden Exporteur von Metallen zu etablieren. Matanzas verfügt über spezialisierte Kais für den Empfang von Rohstoffen wie Bauxit und Kohle sowie für die Verschiffung von Fertigprodukten wie Stahlrollen und Aluminiumbarren. Geografisch profitiert der Hafen von der Wasserkraft der nahegelegenen Guri-Talsperre, die die notwendige Energie für die energieintensiven Industriebetriebe liefert. Die Hafeninfrastruktur ist direkt mit dem Schienennetz verbunden, was den Transport schwerer Lasten innerhalb des Industriekomplexes ermöglicht. Matanzas repräsentiert die industrielle Souveränität Venezuelas und bleibt ein entscheidender Faktor für die metallurgische Wertschöpfungskette des Landes.",
      hu: "Matanzas ipari kikötője Puerto Ordaz ipari zónájának szívében, Ciudad Guayanában található, az Orinoco folyó partján. Ez a logisztikai központja a Corporación Venezolana de Guayana (CVG) hatalmas állami vállalatainak, köztük a SIDOR acélműnek, valamint a VENALUM és ALCASA alumíniumgyártóknak. A kikötőt az 1960-as években tervezték a Guayana-fejlesztési terv részeként, hogy Venezuelát a fémek jelentős exportőrévé tegyék. Matanzas speciális rakpartokkal rendelkezik a nyersanyagok, például a bauxit és a szén fogadására, valamint a késztermékek, például acéltekercsek és alumíniumtömbök szállítására. Földrajzilag a kikötő profitál a közeli Guri-gát által termelt vízenergiából, amely biztosítja az energiaigényes ipari folyamatokhoz szükséges áramot. A kikötői infrastruktúra közvetlenül kapcsolódik a vasúti hálózathoz, lehetővé téve a nehéz rakományok mozgatását az ipari komplexumon belül. Matanzas jelképezi Venezuela ipari önállóságát, és továbbra is meghatározó tényező az ország kohászati értékláncában.",
      ro: "Portul industrial Matanzas este situat în inima zonei industriale din Puerto Ordaz, Ciudad Guayana, pe malul fluviului Orinoco. Acesta servește drept centru logistic pentru marile întreprinderi de stat ale Corporación Venezolana de Guayana (CVG), incluzând combinatul siderurgic SIDOR și producătorii de aluminiu VENALUM și ALCASA. Portul a fost conceput în anii 1960 ca parte integrantă a planului de dezvoltare Guayana, cu scopul de a transforma Venezuela într-un exportator major de metale. Matanzas dispune de dane specializate pentru recepția materiilor prime precum bauxita și cărbunele, dar și pentru expedierea produselor finite, cum ar fi rolele de oțel și lingourile de aluminiu. Geografia portului este avantajoasă datorită proximității față de hidrocentrala Guri, care furnizează energia necesară industriilor electro-intensive din zonă. Infrastructura portuară este conectată direct la rețeaua feroviară, facilitând transportul încărcăturilor grele în cadrul complexului industrial. Matanzas reprezintă pilonul suveranității industriale a Venezuelei în sectorul metalurgic.",
      en: "The Matanzas Industrial Port is located in the heart of the industrial zone of Puerto Ordaz, Ciudad Guayana, along the banks of the Orinoco River. It functions as the primary logistical gateway for the massive state-owned enterprises of the Corporación Venezolana de Guayana (CVG), including the SIDOR steel plant and aluminum producers VENALUM and ALCASA. The port was established in the 1960s as a cornerstone of the Guayana Development Plan, aimed at positioning Venezuela as a global exporter of metals. Matanzas features specialized docks for receiving raw materials like bauxite and coal, as well as for the shipment of finished products such as steel coils and aluminum ingots. Geographically, the port benefits from its proximity to the Guri Dam, which provides the vast amounts of hydroelectric power required for energy-intensive smelting. The port's infrastructure is directly integrated with a dedicated industrial railway system for moving heavy loads. Matanzas stands as a symbol of Venezuela's industrial ambition and remains a critical link in the nation's metallurgical value chain.",
      es: "El puerto de Matanzas es la columna vertebral del suministro logístico de los gigantes industriales de Ciudad Guayana. Aquí, los masivos volúmenes de acero de Sidor y los productos de aluminio de Venalum y Alcasa se cargan en barcos que recorren el Orinoco hacia el mundo. Las instalaciones están diseñadas para materiales pesadísimos y constituyen la interfaz central entre la producción industrial local y los compradores internacionales. Matanzas es un ejemplo de la potencia industrial de Venezuela.",
      pt: "O porto de Matanzas é a espinha dorsal do suprimento logístico para os gigantes industriais de Ciudad Guayana. Aqui, os volumes massivos de aço da Sidor e os produtos de alumínio da Venalum e Alcasa são carregados em navios enviados ao mundo através do Orinoco. As instalações são projetadas para materiais pesadíssimos e formam a interface central entre a produção industrial local e os compradores internacionais. Matanzas é um exemplo do poder industrial da Venezuela.",
      fr: "Le port de Matanzas constitue la colonne vertébrale logistique des géants industriels de Ciudad Guayana. C'est ici que les quantités massives d'acier de Sidor et les produits d'aluminium de Venalum et Alcasa sont chargés sur des navires pour être expédiés dans le monde entier via l'Orénoque. Les installations sont conçues pour les matériaux les plus lourds et servent d'interface centrale entre la production industrielle locale et les clients internationaux. Matanzas illustre la puissance industrielle du Venezuela.",
    },
