    coords: [-70.2189, 11.7511],
    name: { de: "Ölhafen Amuay", hu: "Amuay olajkikötő", ro: "Portul Petrolier Amuay", en: "Amuay Oil Port"},
    description: {
      de: "Ein spezialisierter Tiefwasserhafen, der den Amuay-Raffineriekomplex bedient und für den Export von Erdölprodukten unerlässlich ist.",
      hu: "Speciális mélyvízi kikötő, amely az Amuay finomítót szolgálja ki, és elengedhetetlen a kőolajtermékek exportjához.",
      ro: "Un port specializat cu apă adâncă care deservește rafinăria Amuay și este esențial pentru exportul de produse petroliere.",
      en: "A specialized deep-water port serving the Amuay refinery complex, essential for the export of petroleum products.",
      es: "Un puerto especializado en aguas profundas que da servicio al complejo refinador de Amuay y es esencial para la exportación de productos derivados del petróleo.",
      pt: "Um porto especializado em águas profundas que serve o complexo de refinaria de Amuay e é essencial para a exportação de produtos petrolíferos.",
      fr: "Un port spécialisé en eau profonde desservant le complexe de raffinage d'Amuay et indispensable à l'exportation de produits pétroliers.",
    },
    descriptionAdvanced: {
      de: "Der Ölhafen von Amuay liegt an der Westküste der Halbinsel Paraguaná im Bundesstaat Falcón und ist Teil des Raffineriezentrums Paraguaná (CRP). Er ist einer der bedeutendsten Erdölumschlagplätze der Welt und dient als primärer Exportpunkt für veredelte Ölprodukte wie Benzin, Diesel und Kerosin. Der Hafen wurde in den 1940er Jahren von der Creole Petroleum Corporation (einem Vorläufer von Exxon) erbaut und 1976 im Zuge der Nationalisierung der Ölindustrie von der staatlichen PDVSA übernommen. Geografisch bietet die Bucht von Amuay einen natürlichen Schutz und eine ausreichende Wassertiefe für riesige Öltanker. Die Infrastruktur umfasst zahlreiche Piers, riesige Lagertanklager und ein komplexes Pipelinenetz, das die Raffinerie direkt mit den Verladestationen verbindet. Der Hafen spielt eine strategische Rolle für die Deviseneinnahmen Venezuelas und ist ein Knotenpunkt für den internationalen Energiemarkt. Trotz schwerer Zwischenfälle in der Vergangenheit, wie der Explosion von 2012, bleibt Amuay das pulsierende Herz der venezolanischen Ölindustrie.",
      hu: "Amuay olajkikötője a Paraguaná-félsziget nyugati partján, Falcón államban található, és a Paraguaná Finomító Központ (CRP) szerves részét képezi. Ez a világ egyik legjelentősebb kőolaj-terminálja, amely elsősorban finomított termékek, például benzin, gázolaj és kerozin exportjára szolgál. A kikötőt az 1940-es években a Creole Petroleum Corporation (az Exxon elődje) építette, majd 1976-ban, az olajipar államosításakor került az állami PDVSA tulajdonába. Földrajzilag az Amuay-öböl természetes védelmet és megfelelő vízmélységet biztosít a hatalmas tartályhajók számára. Az infrastruktúra számos mólót, kiterjedt tartályparkokat és egy bonyolult csővezeték-hálózatot foglal magában, amely közvetlenül összeköti a finomítót a töltőállomásokkal. A kikötő stratégiai szerepet játszik Venezuela devizabevételeiben és a nemzetközi energiapiacon. A múltbeli súlyos incidensek, mint például a 2012-es robbanás ellenére Amuay továbbra is a venezuelai olajipar lüktető szíve.",
      ro: "Portul petrolier Amuay este situat pe coasta de vest a peninsulei Paraguaná în statul Falcón și face parte din Complexul de Rafinare Paraguaná (CRP). Este unul dintre cele mai importante terminale petroliere din lume, servind drept punct principal de export pentru produsele rafinate, cum ar fi benzina, motorina și kerosenul. Portul a fost construit în anii 1940 de către Creole Petroleum Corporation (precursorul Exxon) și a fost preluat de compania de stat PDVSA în 1976, în urma naționalizării industriei petroliere. Din punct de vedere geografic, golful Amuay oferă o protecție naturală și o adâncime suficientă pentru tancurile petroliere de dimensiuni gigantice. Infrastructura include numeroase pontoane, parcuri vaste de rezervoare și o rețea complexă de conducte care conectează rafinăria direct de stațiile de încărcare. Portul joacă un rol strategic în veniturile valutare ale Venezuelei și este un nod vital pentru piața energetică internațională. În ciuda incidentelor grave din trecut, precum explozia din 2012, Amuay rămâne inima pulsândă a industriei petroliere venezuelene.",
      en: "The Amuay Oil Port is located on the western shore of the Paraguaná Peninsula in Falcón State and is a key component of the Paraguaná Refining Complex (CRP). It ranks among the world's most significant petroleum terminals, serving as the primary export hub for refined products such as gasoline, diesel, and jet fuel. The port was originally constructed in the 1940s by the Creole Petroleum Corporation (a precursor to Exxon) and was taken over by the state-owned PDVSA in 1976 following the nationalization of the oil industry. Geographically, Amuay Bay provides a natural harbor with sufficient depth to accommodate ultra-large crude carriers and tankers. Its extensive infrastructure consists of multiple piers, vast storage tank farms, and a complex network of pipelines linking the refinery directly to the loading docks. The port plays a strategic role in Venezuela's foreign exchange earnings and acts as a vital node in the global energy market. Despite major historical incidents, such as the 2012 refinery explosion, Amuay remains the operational heart of Venezuela's oil industry.",
      es: "El puerto petrolero de Amuay es uno de los puntos de transbordo más importantes para productos derivados del petróleo en América Latina. Está conectado directamente con uno de los complejos de refinería más grandes del mundo y permite el transporte de gasolina refinada, diésel y otros derivados a los mercados globales. Gracias a su acceso a aguas profundas, pueden atracar aquí enormes petroleros que transportan la producción de energía de Venezuela a todo el mundo. El puerto es el corazón industrial de la península de Paraguaná.",
      pt: "O porto petrolífero de Amuay é um dos pontos de transbordo mais importantes para produtos petrolíferos na América Latina. Está diretamente ligado a um dos maiores complexos de refinaria do mundo e permite o transporte de gasolina refinada, gasóleo e outros derivados para os mercados globais. Graças ao seu acesso a águas profundas, enormes petroleiros podem atracar aqui, transportando a produção de energia da Venezuela para todo o mundo. O porto é o coração industrial da península de Paraguaná.",
      fr: "Le port pétrolier d'Amuay est l'un des points de transbordement les plus importants pour les produits pétroliers en Amérique latine. Il est directement relié à l'un des plus grands complexes de raffinage au monde et permet le transport d'essence raffinée, de diesel et d'autres dérivés vers les marchés mondiaux. Grâce à son accès en eau profonde, d'énormes pétroliers peuvent y accoster pour transporter la production énergétique du Venezuela dans le monde entier. Le port est le cœur industriel de la péninsule de Paraguaná.",
    },
