      hu: ["1967-ben nyílt meg Venezuela első alumíniumkohójaként.", "A CVG és a Reynolds Metals vegyesvállalataként jött létre.", "A primer alumínium beépített kapacitása évi 170 000 tonna.", "Speciális hengerművekkel rendelkezik a fóliagyártáshoz.", "Anyagot szállít a venezuelai autó- és építőipar számára.", "A közeli Caroní-folyóról kapta a nevét."],
