      en: ["Opened in 1967 as Venezuela's first aluminum smelter.", "Established as a joint venture between CVG and Reynolds Metals.", "The installed capacity for primary aluminum is 170,000 tons per year.", "Features specialized rolling mills for aluminum foil production.", "Supplies material for Venezuela's automotive and construction sectors.", "Is named after the nearby Caroní River."],
      es: ["Alcasa representa los inicios del procesamiento de aluminio en Venezuela.", "La planta se ha especializado en productos de aluminio de mayor valor, como láminas y folios.", "Como empresa pionera, Alcasa sentó las bases del complejo industrial de Guayana.", "La producción es un componente importante del valor añadido nacional."],
