      fr: ["Alcasa représente les débuts de la transformation de l'aluminium au Venezuela.", "L'usine s'est spécialisée dans les produits en aluminium à plus haute valeur ajoutée, tels que les feuilles et les tôles.", "En tant qu'entreprise pionnière, Alcasa a jeté les bases du complexe industriel de Guayana.", "La production est un élément important de la valeur ajoutée nationale."],
