    coords: [-71.8667, 11.0167],
    name: { de: "Kohlemine Paso Diablo", hu: "Paso Diablo szénbánya", ro: "Mina de Cărbune Paso Diablo", en: "Paso Diablo Coal Mine"},
    description: {
      de: "Die größte Kohletagebaumine Venezuelas im Guasare-Becken des Bundesstaates Zulia, die qualitativ hochwertige Kraftwerkskohle fördert.",
      hu: "Venezuela legnagyobb külszíni szénbányája a Zulia állambeli Guasare-medencében, amely kiváló minőségű erőművi szenet termel.",
      ro: "Cea mai mare mină de cărbune de suprafață din Venezuela, în bazinul Guasare din statul Zulia, care produce cărbune termic de înaltă calitate.",
      en: "Venezuela's largest open-pit coal mine in the Guasare basin of Zulia state, producing high-quality thermal coal.",
      es: "La mayor mina de carbón a cielo abierto de Venezuela en la cuenca del Guasare, en el estado Zulia, que produce carbón térmico de alta calidad.",
      pt: "A maior mina de carvão a céu aberto da Venezuela na bacia do Guasare, no estado de Zulia, que produz carvão térmico de alta qualidade.",
      fr: "La plus grande mine de charbon à ciel ouvert du Venezuela, située dans le bassin du Guasare dans l'État de Zulia, extrayant du charbon thermique de haute qualité.",
    },
    descriptionAdvanced: {
      de: "Die Kohlemine Paso Diablo ist ein großer Tagebaubetrieb im Guasare-Becken des Bundesstaates Zulia im Nordwesten Venezuelas. Sie ist eine der produktivsten Kohleminen des Landes und bekannt für ihre hochwertige Steinkohle mit geringem Asche- und Schwefelgehalt, was sie auf den internationalen thermischen und metallurgischen Märkten sehr begehrt macht. Der Betrieb begann in den späten 1980er Jahren im Rahmen eines Joint Ventures, an dem das staatliche Unternehmen Carbozulia und internationale Partner beteiligt waren. Zur Infrastruktur der Mine gehört ein spezielles Transportsystem, das die Kohle aus dem Guasare-Tal zu den Verladeterminals am Maracaibo-See befördert. Über Jahrzehnte hinweg war Paso Diablo eine lebenswichtige Devisen- und Beschäftigungsquelle für die Region Zulia und leistete einen bedeutenden Beitrag zum nationalen Energiesektor. Die Mine sieht sich laufenden betrieblichen Herausforderungen in Bezug auf die Wartung der Ausrüstung und die logistische Effizienz gegenüber, bleibt aber eine zentrale Säule der venezolanischen Mineralexporte außerhalb des Erdölsektors. Ihre strategische Lage nahe der kolumbianischen Grenze unterstreicht zudem ihre Bedeutung in der regionalen geopolitischen und wirtschaftlichen Landschaft.",
      hu: "A Paso Diablo szénbánya egy jelentős külszíni fejtés az északnyugat-venezuelai Zulia államban található Guasare-medencében. Az ország egyik legtermelékenyebb szénbányája, amely kiváló minőségű, alacsony hamu- és kéntartalmú bitumenes szenéről ismert, így a nemzetközi energetikai és kohászati piacokon egyaránt keresett termék. A tevékenység az 1980-as évek végén kezdődött az állami Carbozulia és nemzetközi partnerek közös vállalkozásaként. A bánya infrastruktúrája magában foglal egy dedikált szállítási rendszert, amely a szenet a Guasare-völgyből a Maracaibo-tó partján lévő hajózási terminálokhoz juttatja el. Évtizedeken át Paso Diablo létfontosságú devizaforrás és munkahelyteremtő volt Zulia régió számára, jelentősen hozzájárulva a nemzeti energiaszektorhoz. A bánya folyamatos működési kihívásokkal küzd a berendezések karbantartása és a logisztikai hatékonyság terén, mégis a nem olajalapú venezuelai ásványianyag-export egyik tartóoszlopa marad. Stratégiai elhelyezkedése a kolumbiai határ közelében tovább hangsúlyozza jelentőségét a regionális geopolitikai és gazdasági környezetben.",
      ro: "Mina de cărbune Paso Diablo este o operațiune majoră de suprafață situată în bazinul Guasare din statul Zulia, în nord-vestul Venezuelei. Este una dintre cele mai productive mine de cărbune din țară, cunoscută pentru cărbunele bituminos de înaltă calitate, cu un conținut scăzut de cenușă și sulf, ceea ce îl face foarte căutat pe piețele internaționale termice și metalurgice. Operațiunile au început la sfârșitul anilor 1980, în cadrul unui joint venture care a implicat compania de stat Carbozulia și parteneri internaționali. Infrastructura minei include un sistem de transport dedicat care mută cărbunele din valea Guasare către terminalele de transport de pe lacul Maracaibo. Timp de decenii, Paso Diablo a fost o sursă vitală de valută și locuri de muncă pentru regiunea Zulia, contribuind semnificativ la sectorul energetic național. Mina se confruntă cu provocări operaționale continue legate de întreținerea echipamentelor și eficiența logistică, totuși rămâne un pilon central al exporturilor minerale non-petroliere ale Venezuelei. Locația sa strategică lângă granița cu Columbia subliniază, de asemenea, importanța sa în peisajul geopolitic și economic regional.",
      en: "The Paso Diablo coal mine is a major open-pit operation located in the Guasare Basin of Zulia State, in northwestern Venezuela. It is one of the most productive coal mines in the country, known for its high-quality bituminous coal with low ash and sulfur content, making it highly sought after for international thermal and metallurgical markets. Operations began in the late 1980s under a joint venture involving the state-owned Carbozulia and international partners. The mine's infrastructure includes a dedicated transport system that moves coal from the Guasare Valley to the shipping terminals on Lake Maracaibo. For decades, Paso Diablo has been a vital source of foreign exchange and employment for the Zulia region, contributing significantly to the national energy sector. The mine faces ongoing operational challenges related to equipment maintenance and logistical efficiency, yet it remains a central pillar of Venezuela's non-oil mineral exports. Its strategic location near the Colombian border also highlights its importance in the regional geopolitical and economic landscape.",
      es: "Paso Diablo es un centro neurálgico de la minería del carbón en el noroeste de Venezuela. Situada en la cuenca del Guasare, la mina suministra carbón de alta calidad muy demandado internacionalmente, especialmente como carbón para centrales eléctricas. Las dimensiones de la mina a cielo abierto dejan clara la importancia de los recursos fósiles para la región del Zulia. El transporte del carbón a través del Lago de Maracaibo es una proeza logística que hace posible la exportación a ultramar. Paso Diablo es sinónimo de minería industrial en el estado Zulia.",
      pt: "Paso Diablo é um centro de poder da mineração de carvão no noroeste da Venezuela. Localizada na bacia do Guasare, a mina fornece carvão de alta qualidade com grande demanda internacional, especialmente como carvão térmico para usinas elétricas. As dimensões da mina a céu aberto deixam clara a importância dos recursos fósseis para a região de Zulia. O transporte do carvão através do Lago de Maracaibo é uma proeza logística que possibilita a exportação para o exterior. Paso Diablo é sinônimo de mineração industrial no estado de Zulia.",
      fr: "Paso Diablo est le cœur de l'extraction de charbon dans le nord-ouest du Venezuela. Située dans le bassin du Guasare, la mine fournit un charbon de haute qualité, très demandé sur le marché international, notamment pour les centrales électriques. Les dimensions de cette mine à ciel ouvert illustrent l'importance des ressources fossiles pour l'État de Zulia. L'acheminement du charbon via le lac Maracaibo est une prouesse logistique qui rend possible l'exportation outre-mer. Paso Diablo est synonyme d'exploitation minière industrielle dans l'État de Zulia.",
    },
