      ro: ["Este situată în bazinul Guasare, una dintre cele mai mari zone carbonifere.", "Producția de cărbune a început oficial în anul 1987.", "Produce cărbune bituminos de înaltă calitate pentru export global.", "Este operată de Carbones del Guasare, o companie controlată de stat.", "Cărbunele este expediat prin portul Santa Cruz de pe lacul Maracaibo.", "Deține rezerve estimate la câteva sute de milioane de tone."],
      en: ["Located in the Guasare Basin, one of South America's largest coal areas.", "Coal production officially began in 1987.", "Produces high-quality bituminous coal for global export.", "Operated by Carbones del Guasare, a state-controlled company.", "Coal is shipped through the Santa Cruz port on Lake Maracaibo.", "Has estimated reserves of several hundred million tons."],
      es: ["Paso Diablo es el mayor productor de carbón de Venezuela.", "La cadena logística hasta la exportación incluye el transporte por el Lago de Maracaibo.", "La minería del carbón en la cuenca del Guasare ofrece importantes oportunidades de empleo en Zulia.", "La calidad del carbón de Paso Diablo es valorada por su alto poder calorífico."],
      pt: ["Paso Diablo é o maior produtor de carvão da Venezuela.", "A cadeia logística até a exportação inclui o transporte pelo Lago de Maracaibo.", "A mineração de carvão na bacia do Guasare oferece oportunidades significativas de emprego em Zulia.", "A qualidade do carvão de Paso Diablo é valorizada devido ao seu alto poder calorífico."],
