      en: ["Part of the Guasare coal project", "Hard coal mining", "Creates many local jobs", "Important part of the Zulia economy"],
      es: ["Pertenece al proyecto carbonífero del Guasare", "Extracción de hulla", "Crea muchos empleos locales", "Parte importante de la economía de Zulia"],
      pt: ["Pertence ao projeto de carvão do Guasare", "Mineração de carvão mineral", "Cria muitos empregos locais", "Parte importante da economia de Zulia"],
