      hu: ["Északnyugat-Zuliában, a Guasare-szénkomplexum részeként működik.", "Magas fűtőértékű energetikai szenet termel.", "Főként az európai és észak-amerikai piacokra exportál.", "A széntelérek a paleocén korú Guasare-formáció részét képezik.", "Hatalmas markolókat és teherautó-flottákat használ a külszíni fejtéshez.", "Stratégiai szempontból állami vállalatok irányítása alatt áll Zuliában."],
      ro: ["Face parte din complexul carbonifer Guasare din nord-vestul statului Zulia.", "Produce cărbune termic cu putere calorifică ridicată.", "Exportă în principal pe piețele europene și nord-americane.", "Straturile de cărbune fac parte din formațiunea paleocenă Guasare.", "Utilizează excavatoare mari și flote de camioane pentru exploatarea de suprafață.", "Este administrată strategic de companii de stat din Zulia."],
      en: ["Part of the Guasare coal complex in northwestern Zulia.", "Produces thermal coal with high calorific value.", "Exports primarily to European and North American markets.", "The coal seams are part of the Paleocene Guasare formation.", "Uses large excavators and truck fleets for open-pit mining.", "Strategically managed by state-owned companies in Zulia."],
      es: ["Mina Norte es una parte integrante del complejo carbonífero del Guasare.", "Complementa significativamente las capacidades de exportación de Zulia.", "El trabajo en Mina Norte es un motor económico esencial para la comunidad circundante.", "La extracción de carbón supone una contribución estratégica al rendimiento económico nacional."],
      pt: ["A Mina Norte é parte integrante do maior complexo de carvão do Guasare.", "Complementa significativamente as capacidades de exportação de Zulia.", "O trabalho na Mina Norte é um motor econômico essencial para a comunidade local.", "A extração de carvão dá uma contribuição estratégica para o desempenho econômico nacional."],
