    type: "industry",
    parent: "VE-D",
    coords: [-67.1667, 10.15],
    name: { de: "Nickelmine Loma de Níquel", hu: "Loma de Níquel nikkelbánya", ro: "Mina de Nichel Loma de Níquel", en: "Loma de Níquel Mine"},
    description: {
      de: "Ein integrierter Bergbau- und Schmelzkomplex, der Ferronickel für den globalen Edelstahlmarkt produziert.",
      hu: "Integrált bányászati és kohászati komplexum, amely ferronikkelt állít elő a globális rozsdamentes acél piac számára.",
      ro: "Un complex integrat de minerit și topire care produce feronichel pentru piața globală a oțelului inoxidabil.",
      en: "An integrated mining and smelting complex producing ferronickel for the global stainless steel market.",
      es: "Un complejo integrado de minería y fundición que produce ferroníquel para el mercado mundial del acero inoxidable.",
      pt: "Um complexo integrado de mineração e fundição que produz ferroníquel para o mercado global de aço inoxidável.",
      fr: "Un complexe minier et de fonderie intégré qui produit du ferronickel pour le marché mondial de l'acier inoxydable.",
    },
    descriptionAdvanced: {
      de: "Loma de Níquel ist Venezuelas wichtiger Nickelabbau- und Raffineriekomplex an der Grenze zwischen den Bundesstaaten Aragua und Miranda. Es handelt sich um einen Tagebaubetrieb, in dem lateritisches Nickelerz gewonnen wird, das dann vor Ort in einer spezialisierten Schmelzanlage zu Ferronickel verarbeitet wird. Das Projekt wurde ursprünglich vom multinationalen Konzern Anglo American entwickelt und nahm im Jahr 2000 die Produktion auf, was einen bedeutenden technologischen Fortschritt für die metallurgische Industrie des Landes darstellte. Im Jahr 2012 übernahm die venezolanische Regierung die vollständige Kontrolle über den Betrieb, nachdem die Bergbaukonzessionen ausgelaufen waren und nicht verlängert wurden. Die Anlage liegt strategisch günstig in der Nähe des nationalen Stromnetzes und wichtiger Transportwege, was den Transport der raffinierten Produkte zu Industriezentren und Häfen erleichtert. Die Produktion von Loma de Níquel ist für die Herstellung von Edelstahl und verschiedene High-Tech-Anwendungen sowohl im Inland als auch international unverzichtbar. Der Standort bleibt einer der wenigen bedeutenden Nickelproduzenten in der Karibikregion, auch wenn er in den letzten Jahren aufgrund technischer und wirtschaftlicher Faktoren mit Produktionsschwankungen konfrontiert war.",
      hu: "Loma de Níquel Venezuela elsődleges nikkelbányászati és finomító komplexuma, amely Aragua és Miranda államok határán található. Ez egy külszíni fejtés, ahol laterites nikkelércet termelnek ki, amelyet azután a helyszínen, egy speciális kohóműben ferronikkel előállítására dolgoznak fel. A projektet eredetileg a multinacionális Anglo American fejlesztette ki, és 2000-ben kezdte meg a termelést, ami jelentős technológiai előrelépést jelentett az ország kohászati ipara számára. 2012-ben a venezuelai kormány vette át a teljes ellenőrzést a műveletek felett, miután a bányászati koncessziók lejártak, és nem hosszabbították meg azokat. A létesítmény stratégiailag az országos villamosenergia-hálózat és a főbb szállítási útvonalak közelében helyezkedik el, ami megkönnyíti a finomított termékek ipari központokba és kikötőkbe történő eljutását. A Loma de Níquel termelése elengedhetetlen a rozsdamentes acél gyártásához és különféle csúcstechnológiai alkalmazásokhoz, belföldön és nemzetközi szinten egyaránt. A helyszín továbbra is a Karib-tenger térségének kevés jelentős nikkeltermelőjének egyike, bár az elmúlt években technikai és gazdasági tényezők miatt termelési ingadozásokkal szembesült.",
      ro: "Loma de Níquel este principalul complex de extracție și rafinare a nichelului din Venezuela, situat la granița dintre statele Aragua și Miranda. Este o operațiune de suprafață care extrage minereu de nichel lateritic, care este apoi procesat la fața locului într-o instalație de topire specializată pentru a produce feronichel. Proiectul a fost dezvoltat inițial de multinaționala Anglo American și a început producția în anul 2000, reprezentând un avans tehnologic semnificativ pentru industria metalurgică a țării. În 2012, guvernul venezuelean a preluat controlul deplin asupra operațiunilor, după ce concesiunile miniere au expirat și nu au fost reînnoite. Instalația este situată strategic lângă rețeaua electrică națională și rutele majore de transport, facilitând mișcarea produselor rafinate către centrele industriale și porturi. Producția de la Loma de Níquel este esențială pentru fabricarea oțelului inoxidabil și pentru diverse aplicații de înaltă tehnologie, atât pe plan intern, cât și internațional. Situl rămâne unul dintre puținii producători semnificativi de nichel din regiunea Caraibilor, deși s-a confruntat cu variații de producție din cauza factorilor tehnici și economici în ultimii ani.",
      en: "Loma de Níquel is Venezuela's primary nickel mining and refining complex, located on the border between the Aragua and Miranda states. It is an open-pit operation that extracts lateritic nickel ore, which is then processed on-site in a specialized smelting plant to produce ferronickel. The project was originally developed by the multinational Anglo American and began production in 2000, representing a significant technological advancement for the country's metallurgical industry. In 2012, the Venezuelan government took full control of the operations after the mining concessions expired and were not renewed. The facility is strategically located near the national power grid and major transportation routes, facilitating the movement of refined products to industrial centers and ports. Loma de Níquel's production is essential for stainless steel manufacturing and various high-tech applications, both domestically and internationally. The site remains one of the few significant nickel producers in the Caribbean region, although it has faced production variations due to technical and economic factors in recent years.",
      es: "Loma de Níquel es una planta tecnológicamente altamente especializada situada en la frontera entre los estados de Aragua y Miranda. Aquí se extrae níquel y se procesa directamente in situ para obtener ferroníquel, una materia prima esencial para la producción de acero inoxidable de alta calidad. La planta es un ejemplo de la diversificación de la industria minera venezolana más allá del oro y el petróleo. Subraya el papel de Venezuela como proveedor de materiales industriales especializados para el mercado mundial.",
      pt: "Loma de Níquel é uma planta tecnologicamente altamente especializada na fronteira entre os estados de Aragua e Miranda. Aqui, o níquel é extraído e processado diretamente no local para produzir ferroníquel, uma matéria-prima essencial para a produção de aço inoxidável de alta qualidade. A planta é um exemplo da diversificação da indústria mineradora venezuelana para além do ouro e do petróleo. Sublinha o papel da Venezuela como fornecedora de materiais industriais especializados no mercado mundial.",
      fr: "Loma de Níquel est une installation technologiquement spécialisée située à la frontière entre les États d'Aragua et de Miranda. Le nickel y est extrait puis transformé directement sur place en ferronickel, une matière première essentielle à la production d'acier inoxydable de haute qualité. L'usine illustre la diversification de l'industrie minière vénézuélienne au-delà de l'or et du pétrole. Elle souligne le rôle du Venezuela en tant que fournisseur de matériaux industriels spécialisés sur le marché mondial.",
    },
