    coords: [-64.8417, 10.1083],
    name: { de: "Petrochemiekomplex Jose", hu: "Jose petrolkémiai komplexum", ro: "Complexul Petrochimic Jose", en: "Jose Petrochemical Complex"},
    image: "/poi-images/jose-petrochemical-complex-economic-v2.webp",
    description: {
      de: "Das industrielle Herzstück für die Aufbereitung von extra schwerem Rohöl aus dem Orinoco-Gürtel, gelegen an der Ostküste.",
      hu: "Az Orinoco-övezetből származó extra nehéz nyersolaj feldolgozásának ipari központja, amely a keleti parton található.",
      ro: "Piesa centrală industrială pentru prelucrarea țițeiului extra greu din Centura Orinoco, situată pe coasta de est.",
      en: "The industrial centerpiece for upgrading extra heavy crude oil from the Orinoco Belt, located on the east coast.",
      es: "El corazón industrial para el mejoramiento de crudo extrapesado de la Faja del Orinoco, situado en la costa oriental.",
      pt: "O coração industrial para o aprimoramento do petróleo bruto extrapesado da Faixa do Orinoco, localizado na costa leste.",
      fr: "Le cœur industriel pour la valorisation du pétrole brut extra-lourd de la ceinture de l'Orénoque, situé sur la côte est.",
    },
    descriptionAdvanced: {
      de: "Der Jose-Petrochemiekomplex, offiziell Complejo Industrial y Petroquímico José Antonio Anzoátegui, ist ein riesiges Industriezentrum an der Küste des Bundesstaates Anzoátegui. Er dient als eines der wichtigsten Zentren für die Verarbeitung von schwerem und extraschwerem Rohöl aus dem Orinoco-Gürtel sowie als bedeutender Standort für die petrochemische Produktion. Der Komplex beherbergt mehrere Anlagen, darunter Rohöl-Upgrader, Ammoniak- und Harnstoffanlagen sowie spezialisierte Verladeterminals für Schwefel und Petrolkoks. Er wurde in den 1990er Jahren entwickelt und steht für die Integration des venezolanischen Öl- und Gassektors mit der hochwertigen chemischen Produktion. Der Standort ist ein entscheidender Motor für die regionale Wirtschaft, bietet Tausende von Arbeitsplätzen und unterstützt eine Vielzahl von nachgelagerten Industrien. Als zentraler Knotenpunkt der nationalen Energieinfrastruktur ist der Jose-Komplex lebenswichtig für die Herstellung von Düngemitteln und Industriechemikalien, die die heimische Landwirtschaft und Fertigung unterstützen. Seine strategische Lage an der Küste ermöglicht effiziente Exporte in großem Maßstab auf die Weltmärkte und macht ihn zu einem Eckpfeiler der industriellen Präsenz Venezuelas im Atlantikbecken.",
      hu: "A Jose petrolkémiai komplexum, hivatalos nevén Complejo Industrial y Petroquímico José Antonio Anzoátegui, egy hatalmas ipari központ Anzoátegui állam tengerpartján. Az Orinoco-övezetből származó nehéz- és extranehéz kőolaj feldolgozásának egyik legfontosabb központjaként szolgál, emellett a vegyipari termelés kiemelt helyszíne. A komplexum több létesítménynek ad otthont, köztük kőolaj-nemesítőknek, ammónia- és karbamidüzemeknek, valamint speciális hajózási termináloknak a kén és a petrolkoksz számára. Az 1990-es években fejlesztették ki, és a venezuelai olaj- és gázszektor, valamint a magas hozzáadott értékű vegyianyag-gyártás integrációját jelképezi. A terület a regionális gazdaság meghatározó motorja, több ezer munkahelyet biztosít, és számos kapcsolódó iparágat támogat. A nemzeti energetikai infrastruktúra központi csomópontjaként a Jose komplexum létfontosságú a hazai mezőgazdaságot és gyártást segítő műtrágyák és ipari vegyszerek előállításához. Stratégiai partmenti elhelyezkedése lehetővé teszi a hatékony, nagyüzemi exportot a globális piacokra, amivel Venezuela ipari jelenlétének alapkövévé vált az atlanti térségben.",
      ro: "Complexul petrochimic Jose, numit oficial Complejo Industrial y Petroquímico José Antonio Anzoátegui, este un centru industrial masiv situat pe coasta statului Anzoátegui. Acesta servește ca unul dintre cele mai importante puncte pentru procesarea țițeiului greu și extrasugreu din Centura Orinoco, precum și ca sit major pentru producția petrochimică. Complexul găzduiește multiple facilități, inclusiv unități de îmbunătățire a țițeiului, fabrici de amoniac și uree, și terminalele specializate de transport pentru sulf și cocs de petrol. Dezvoltat în anii 1990, acesta reprezintă integrarea sectoarelor de petrol și gaze din Venezuela cu producția chimică de mare valoare. Situl este un motor critic pentru economia regională, oferind mii de locuri de muncă și susținând o gamă largă de industrii din aval. Ca nod central în infrastructura energetică națională, complexul Jose este vital pentru producția de îngrășăminte și substanțe chimice industriale care susțin agricultura și producția internă. Locația sa strategică pe coastă permite exporturi eficiente la scară largă către piețele globale, făcându-l o piatră de temelie a prezenței industriale a Venezuelei în bazinul Atlanticului.",
      en: "The Jose Petrochemical Complex, officially named the Complejo Industrial y Petroquímico José Antonio Anzoátegui, is a massive industrial hub located on the coast of Anzoátegui State. It serves as one of the most important centers for the processing of heavy and extra-heavy crude oil from the Orinoco Belt, as well as a major site for petrochemical production. The complex houses multiple facilities, including crude oil upgraders, ammonia and urea plants, and specialized shipping terminals for sulfur and petroleum coke. Developed in the 1990s, it represents the integration of Venezuela's oil and gas sectors with high-value chemical manufacturing. The site is a critical engine for the regional economy, providing thousands of jobs and supporting a wide range of downstream industries. As a central node in the national energy infrastructure, the Jose complex is vital for the production of fertilizers and industrial chemicals that support domestic agriculture and manufacturing. Its strategic coastal location allows for efficient large-scale exports to global markets, making it a cornerstone of Venezuela's industrial presence in the Atlantic basin.",
      es: "El Complejo Jose es el puente industrial entre los vastos depósitos de la Faja del Orinoco y los mercados internacionales. Aquí, el crudo extrapesado extraído en el interior del país se procesa para obtener productos petrolíferos comercializables. Su ubicación en la costa este permite la exportación directa a través de grandes terminales de tanqueros. Jose es un parque industrial altamente complejo y un factor decisivo para la estrategia de exportación de petróleo de Venezuela.",
      pt: "O Complexo Jose é a ponte industrial entre as vastas jazidas da Faixa do Orinoco e os mercados internacionais. Aqui, o petróleo bruto extrapesado extraído no interior do país é processado em produtos petrolíferos comercializáveis. Sua localização na costa leste permite a exportação direta através de grandes terminais de navios-tanque. Jose é um parque industrial altamente complexo e um fator decisivo para a estratégia de exportação de petróleo da Venezuela.",
      fr: "Le complexe Jose est le pont industriel entre les vastes gisements de la ceinture de l'Orénoque et les marchés internationaux. Ici, le pétrole brut extra-lourd extrait à l'intérieur du pays est traité en produits pétroliers commercialisables. Sa situation sur la côte est permet une exportation directe via de grands terminaux pétroliers. Jose est un parc industriel hautement complexe et un facteur décisif pour la stratégie d'exportation de pétrole du Venezuela.",
    },
