      hu: ["Hivatalosan José Antonio Anzoátegui függetlenségi hősről nevezték el.", "Az Orinoco-övezetből származó kőolaj exportjának legfőbb csomópontja.", "Hatalmas nitrogénműtrágya-gyártó üzemeknek ad otthont.", "Speciális terminálokkal rendelkezik a szilárd kén szállításához.", "Központi szerepet játszik a Pequiven állami vállalattal való együttműködésben.", "A komplexum több ezer hektáros területet foglal el."],
      ro: ["Numit oficial după eroul independenței José Antonio Anzoátegui.", "Cel mai important punct de export pentru țițeiul din Centura Orinoco.", "Găzduiește instalații mari pentru producția de îngrășăminte cu azot.", "Dispune de terminale specializate pentru transportul sulfului solid.", "Joacă un rol central în parteneriatul strategic cu compania Pequiven.", "Complexul se întinde pe o suprafață de câteva mii de hectare."],
      en: ["Officially named after independence hero José Antonio Anzoátegui.", "Main export hub for crude oil coming from the Orinoco Belt.", "Houses large facilities for the production of nitrogen fertilizers.", "Features specialized terminals for the shipment of solid sulfur.", "Plays a central role in the strategic partnership with Pequiven.", "The complex covers an area of several thousand hectares."],
      es: ["Jose es el sitio más importante para el mejoramiento de crudo pesado del Orinoco.", "Las terminales están diseñadas para los tanqueros más grandes del mundo.", "El gas natural líquido (LGN) es un subproducto importante del proceso de mejoramiento.", "El sitio Jose funciona como una puerta de enlace crucial para todas las exportaciones de petróleo de la región oriental."],
      pt: ["Jose é o local mais importante para o aprimoramento do petróleo pesado do Orinoco.", "Os terminais são projetados para os maiores navios-tanque do mundo.", "O gás natural líquido (LGN) é um subproduto importante do processo de processamento.", "O local de Jose funciona como um portal crucial para todas as exportações de petróleo da região leste."],
      fr: ["Jose est le site le plus important pour la valorisation du pétrole lourd de l'Orénoque.", "Les terminaux sont conçus pour les plus grands pétroliers du monde.", "Le gaz naturel liquide (GNL) est un sous-produit important du processus de traitement.", "Le site de Jose fait office de porte d'entrée cruciale pour l'ensemble des exportations pétrolières de la région orientale."],
