    coords: [-68.1833, 10.4833],
    name: { de: "Petrochemiekomplex Morón", hu: "Morón petrolkémiai komplexum", ro: "Complexul Petrochimic Morón", en: "Morón Petrochemical Complex"},
    image: "/poi-images/moron-petrochemical-complex-economic-v2.webp",
    description: {
      de: "Der älteste petrochemische Komplex in Venezuela, spezialisiert auf die Produktion von Düngemitteln und landwirtschaftlichen Chemikalien.",
      hu: "Venezuela legrégebbi petrolkémiai komplexuma, amely műtrágyák és mezőgazdasági vegyszerek gyártására specializálódott.",
      ro: "Cel mai vechi complex petrochimic din Venezuela, specializat în producția de îngrășăminte și substanțe chimice agricole.",
      en: "The oldest petrochemical complex in Venezuela, specializing in the production of fertilizers and agricultural chemicals.",
      es: "El complejo petroquímico más antiguo de Venezuela, especializado en la producción de fertilizantes y productos químicos agrícolas.",
      pt: "O complexo petroquímico mais antigo da Venezuela, especializado na produção de fertilizantes e produtos químicos agrícolas.",
      fr: "Le plus ancien complexe pétrochimique du Venezuela, spécialisé dans la production d'engrais et de produits chimiques agricoles.",
    },
    descriptionAdvanced: {
      de: "Der Petrochemiekomplex Morón in der Nähe der Stadt Morón im Bundesstaat Carabobo ist der älteste und etablierteste petrochemische Standort in Venezuela. Er wurde 1953 gegründet und markierte den Beginn der Bemühungen des Landes, seine Kohlenwasserstoffressourcen über die einfache Raffination hinaus zu veredeln. Der Komplex wird von Pequiven, dem staatlichen Petrochemieunternehmen, betrieben und konzentriert sich primär auf die Produktion von Düngemitteln wie Harnstoff und Phosphaten sowie Schwefelsäure und anderen Basischemikalien. Seine Lage in der Nähe des Hafens von Puerto Cabello bietet einen strategischen Vorteil sowohl für den Empfang von Rohstoffen als auch für die Verteilung von Fertigprodukten in die landwirtschaftlichen Zentren Venezuelas. Im Laufe der Jahrzehnte wurde der Morón-Komplex mehrfach erweitert und modernisiert, um seine Rolle als Hauptlieferant für den nationalen Agrarsektor zu behaupten. Die Anlage ist unverzichtbar für die Gewährleistung der heimischen Ernährungssicherheit, da sie die notwendigen Mittel für die Bodenverbesserung bereitstellt. Trotz seines Alters bleibt Morón ein Symbol für das industrielle Erbe Venezuelas und ist weiterhin ein wichtiger Bestandteil der diversifizierten Wirtschaftsstrategie des Landes.",
      hu: "A Morón petrolkémiai komplexum, amely Carabobo államban, Morón városa közelében található, Venezuela legrégebbi és legmeghatározóbb vegyipari létesítménye. 1953-ban alapították, ami az ország azon törekvéseinek kezdetét jelezte, hogy a szénhidrogén-készleteit az egyszerű finomításon túl is hasznosítsa. A komplexumot az állami Pequiven vegyipari vállalat üzemelteti, és elsősorban műtrágyák, például karbamid és foszfátok, valamint kénsav és más alapvető vegyszerek gyártására összpontosít. A Puerto Cabello kikötőjéhez közeli elhelyezkedése stratégiai előnyt jelent mind a nyersanyagok fogadása, mind a késztermékek elosztása szempontjából Venezuela mezőgazdasági területei felé. Az évtizedek során a Morón komplexum több bővítésen és modernizáción esett át, hogy megőrizze szerepét a nemzeti agrárszektor elsődleges beszállítójaként. A létesítmény elengedhetetlen a hazai élelmezésbiztonság garantálásához, mivel biztosítja a talajjavításhoz szükséges alapanyagokat. Kora ellenére Morón Venezuela ipari örökségének szimbóluma marad, és továbbra is a nemzet diverzifikált gazdasági stratégiájának létfontosságú eleme.",
      ro: "Complexul petrochimic Morón, situat lângă orașul Morón din statul Carabobo, este cel mai vechi și mai bine stabilit sit petrochimic din Venezuela. Fondat în 1953, acesta a marcat începutul eforturilor țării de a adăuga valoare resurselor sale de hidrocarburi dincolo de simpla rafinare. Complexul este operat de Pequiven, compania petrochimică de stat, și se concentrează în principal pe producția de îngrășăminte, cum ar fi ureea și fosfații, precum și acidul sulfuric și alte substanțe chimice de bază. Locația sa lângă Portul Puerto Cabello oferă un avantaj strategic atât pentru primirea materiilor prime, cât și pentru distribuirea produselor finite către zonele agricole din Venezuela. De-a lungul deceniilor, complexul Morón a trecut prin mai multe extinderi și modernizări pentru a-și menține rolul de furnizor principal pentru sectorul agricol național. Instalația este esențială pentru asigurarea securității alimentare interne prin furnizarea inputurilor necesare pentru îmbunătățirea solului. În ciuda vechimii sale, Morón rămâne un simbol al moștenirii industriale a Venezuelei și continuă să fie o componentă vitală a strategiei economice diversificate a națiunii.",
      en: "The Morón Petrochemical Complex, located near the town of Morón in Carabobo State, is the oldest and most established petrochemical site in Venezuela. Founded in 1953, it marked the beginning of the country's efforts to add value to its hydrocarbon resources beyond simple refining. The complex is operated by Pequiven, the state petrochemical company, and focuses primarily on the production of fertilizers, such as urea and phosphates, as well as sulfuric acid and other basic chemicals. Its location near the Port of Puerto Cabello provides a strategic advantage for both receiving raw materials and distributing finished products to the agricultural heartlands of Venezuela. Over the decades, the Morón complex has undergone several expansions and modernizations to maintain its role as a primary supplier for the national farming sector. The facility is essential for ensuring domestic food security by providing the necessary inputs for soil enrichment. Despite its age, Morón remains a symbol of Venezuela's industrial heritage and continues to be a vital component of the nation's diversified economic strategy.",
      es: "Morón es una sede pionera de la petroquímica venezolana. Especializado en fertilizantes y agroquímicos, el complejo apoya significativamente la producción agrícola en toda Venezuela. La planta, situada cerca de Puerto Cabello, muestra cómo los procesos petroquímicos se utilizan directamente para promover la seguridad alimentaria y la productividad agrícola. El complejo no solo tiene importancia histórica, sino que hoy en día es un componente indispensable de la infraestructura industrial.",
      pt: "Morón é um local pioneiro da petroquímica venezuelana. Com especialização em fertilizantes e agroquímicos, o complexo apoia significativamente a produção agrícola em toda a Venezuela. A instalação próxima a Puerto Cabello mostra como os processos petroquímicos são usados diretamente para promover a segurança alimentar e a produtividade agrícola. O complexo não é apenas historicamente significativo, mas também hoje um componente indispensável da infraestrutura industrial.",
      fr: "Morón est un site pionnier de la pétrochimie vénézuélienne. Grâce à sa spécialisation dans les engrais et l'agrochimie, le complexe soutient largement la production agricole dans tout le pays. L'installation située près de Puerto Cabello illustre l'utilisation directe des processus pétrochimiques pour favoriser la sécurité alimentaire et la productivité agricole. Le complexe n'est pas seulement important d'un point de vue historique ; il constitue aujourd'hui un pilier indispensable de l'infrastructure industrielle.",
    },
