      hu: ["Venezuela első petrolkémiai komplexuma, 1953-ban alapították.", "A mezőgazdaság számára fontos foszfátműtrágyák fő gyártója.", "A stratégiai jelentőségű Puerto Cabello kikötőjének közvetlen közelében van.", "Az állami tulajdonú Pequiven vállalat irányítása alatt áll.", "Hatalmas kénsavgyártó kapacitással rendelkezik.", "A nemzeti műtrágyaellátás központi helyszíne."],
      ro: ["Primul complex petrochimic din Venezuela, fondat în 1953.", "Principalul producător de îngrășăminte cu fosfați pentru agricultură.", "Situat în imediata apropiere a portului strategic Puerto Cabello.", "Operat de holdingul de stat Pequiven.", "Deține capacități mari pentru producția de acid sulfuric.", "Locație centrală pentru aprovizionarea națională cu îngrășăminte."],
      en: ["First petrochemical complex in Venezuela, founded in 1953.", "Main producer of phosphate fertilizers for the agricultural sector.", "Located in close proximity to the strategic Port of Puerto Cabello.", "Operated by the state-owned holding Pequiven.", "Has large capacities for the production of sulfuric acid.", "Central location for national fertilizer supply."],
      es: ["Morón es la sede petroquímica más antigua de Venezuela.", "La producción de urea y amoníaco es central para el abastecimiento de la agricultura.", "Pequiven, como operador, integra la sede en la red industrial nacional.", "Su ubicación cerca de Puerto Cabello optimiza la distribución logística de los productos agrícolas."],
      pt: ["Morón é o local petroquímico mais antigo da Venezuela.", "A produção de ureia e amônia é central para o abastecimento da agricultura.", "A Pequiven como operadora integra o local na rede industrial nacional.", "A localização próxima a Puerto Cabello otimiza a distribuição logística dos produtos agrícolas."],
