      es: ["Caruachi fue construida como parte de un plan a gran escala para ampliar la capacidad hidroeléctrica.", "La planta contribuye significativamente al suministro de las industrias del acero y el aluminio.", "El Río Caroní es uno de los ríos con mayor potencial energético de Sudamérica.", "La integración en la red eléctrica nacional es estratégicamente esencial para Venezuela."],
